HDR = ['id', 'domain', 'entity', 'class', 'blueprint', 'required field groups', 'APG today (record kind: fields)', 'status', 'gap',
       'systems supported by the survey (codes)', 'likely also (judgement, unverified)', 'APG supply paths', 'path status', 'likely data owner', 'links to']


def status(today):
    t = today.split(':')[0].strip()
    return {'covered': 'covered', 'partial': 'partial', 'partly': 'partial'}.get(t, 'missing')


SUP = collections.defaultdict(set)
for s in csv.DictReader(open('SYSTEMS_SURVEY.csv')):
    for e in s['APG entities the cited source says the system holds (ids in ENTITY_REGISTER.csv; holding is not a confirmed APG feed)'].split():
        SUP[e].add(s['code'])
ROWS.sort(key=lambda r: int(r[0][1:]))
with open('ENTITY_REGISTER.csv', 'w', newline='') as fh:
    w = csv.writer(fh, lineterminator='\n')
    w.writerow(HDR)
    for r in ROWS:
        sup = sorted(SUP[r[0]])
        judged = [c.strip() for c in r[8].split(',') if c.strip() and c.strip() != '-' and c.strip() not in sup]
        w.writerow(list(r[:6]) + [r[6], status(r[6]), r[7], ', '.join(sup) or '-', ', '.join(judged) or '-'] + list(r[9:]))

ids = [r[0] for r in ROWS]
assert len(ids) == len(set(ids)), 'duplicate id'
for r in ROWS:
    paths = [p.strip()[0] for p in r[9].split(',') if p.strip()]
    marked = {part.strip().split()[0] for part in r[10].split(';')}
    assert set(paths) == marked, (r[0], paths, marked)
    if status(r[6]) == 'covered':
        assert r[7] == '-', r[0]
    else:
        assert r[7] != '-', r[0]
c = collections.Counter(status(r[6]) for r in ROWS)
print('entities', len(ROWS), dict(c))
for cls in 'BCIDXV':
    print(cls, sum(1 for r in ROWS if r[3] == cls), {s: sum(1 for r in ROWS if r[3] == cls and status(r[6]) == s) for s in ('covered', 'partial', 'missing')})
